    "kbit/s · CBR = feste Rate, ABR = variables Ziel.": "kbit/s · CBR = tasa fija, ABR = objetivo variable.",
    "Reines Encoding ohne Test-Encodes. Für Vergleiche und automatische Wertfindung das": "Codificación pura sin codificaciones de prueba. Para comparaciones y búsqueda automática de valores usa la",
    "nutzen und den Gewinner übernehmen.": "y aplicar el ganador.",
