    "Dynamik (HDR / Dolby Vision)": "Plage dynamique (HDR / Dolby Vision)",
    "Automatisch je Datei (empfohlen)": "Automatique par fichier (recommandé)",
    "HDR / Dolby Vision beibehalten": "Conserver HDR / Dolby Vision",
    "HDR behalten · Dolby Vision verwerfen": "Conserver HDR · abandonner Dolby Vision",
    "Automatisch wählt pro Datei die sinnvolle Behandlung: Dolby Vision (RPU) bzw. HDR10/HLG bleiben erhalten, SDR bleibt SDR. DV-Reinjektion (Profil 8.1) gilt nur für HEVC bzw. AV1 auf der CPU.":
      "Le mode automatique choisit le traitement adapté par fichier : Dolby Vision (RPU) et HDR10/HLG sont conservés, le SDR reste SDR. La réinjection DV (profil 8.1) ne s'applique qu'au HEVC ou à l'AV1 sur le CPU.",
    "Keine": "Aucun",
    "Bitte prüfen, bevor der Stapel startet:": "À vérifier avant de lancer le lot :",
    "Trotzdem fortfahren?": "Continuer quand même ?",
    "Dateien ausgewählt – das kann sehr lange dauern und viel Speicher belegen.":
      "fichiers sélectionnés – cela peut être très long et occuper beaucoup d'espace.",
    "Die Auswahl enthält sehr unterschiedliche Qualitäten/Auflösungen. Eine einzige feste Einstellung liefert dann uneinheitliche Ergebnisse – „Ziel-VMAF (pro Datei)\" passt sich besser an.":
      "La sélection contient des qualités/résolutions très différentes. Un seul réglage fixe donnera des résultats hétérogènes ; « VMAF cible (par fichier) » s'adapte mieux.",
    "HDR- und SDR-Dateien gemischt, aber die Dynamik ist fest eingestellt. „Automatisch je Datei\" behandelt jede Datei korrekt.":
      "Fichiers HDR et SDR mélangés, mais la plage dynamique est fixe. « Automatique par fichier » traite chaque fichier correctement.",
    "Sprach-Whitelist Ton": "Liste blanche de langues audio",
    "Sprach-Whitelist Untertitel": "Liste blanche de langues de sous-titres",
    "z. B. de, en (leer = alle behalten)": "p. ex. de, en (vide = tout conserver)",
    "Nur Tonspuren dieser Sprachen behalten. Findet sich keine passende Spur, bleiben alle erhalten (kein Ton-Verlust). Manuelle Spurauswahl in der Liste hat Vorrang.":
      "Ne conserver que les pistes audio de ces langues. Si aucune ne correspond, toutes sont conservées (pas de perte audio). La sélection manuelle dans la liste est prioritaire.",
    "Nur Untertitel dieser Sprachen behalten (leer = alle). Ohne Treffer werden keine Untertitel übernommen.":
      "Ne conserver que les sous-titres de ces langues (vide = tous). Si aucun ne correspond, aucun sous-titre n'est conservé.",
    "Warnung ab Anzahl Dateien": "Avertir à partir de N fichiers",
    "Vor dem Start warnen, wenn so viele (oder mehr) Dateien ausgewählt sind (0 = keine Warnung). Wird lokal gespeichert.":
      "Avertir avant le démarrage lorsque autant de fichiers (ou plus) sont sélectionnés (0 = aucun avertissement). Enregistré localement.",
    "Nur Remuxen (ohne Neucodierung) – nur Spuren/Container ändern":
      "Remux uniquement (sans réencodage) – changer seulement pistes/conteneur",
    "Ziel-Container (Remux)": "Conteneur cible (remux)",
    "Wie Quelle": "Comme la source",
    "Das Video wird 1:1 übernommen (kein Re-Encode). Ton/Untertitel filtern sich über die Spurauswahl bzw. die Sprach-Whitelist. Kapitel, Attachments und Metadaten bleiben erhalten.":
      "La vidéo est copiée à l'identique (sans réencodage). L'audio/les sous-titres sont filtrés via la sélection de pistes ou la liste blanche de langues. Les chapitres, pièces jointes et métadonnées sont conservés.",
    "Alle Dateien haben dieselben Spuren – Auswahl für alle übernehmen:":
      "Tous les fichiers ont les mêmes pistes – appliquer la sélection à tous :",
    "Gemeinsame Spuren aller Dateien – Auswahl für alle übernehmen:":
      "Pistes communes à tous les fichiers – appliquer la sélection à tous :",
    "Sonder-Spuren einzelner Dateien bleiben unberührt und können pro Zeile angepasst werden.":
      "Les pistes spéciales de fichiers individuels restent intactes et peuvent être ajustées par ligne.",
    "Ins Remux übernehmen": "Transférer vers Remux",
    "Medien & Ausgabe": "Médias et sortie",
    "Standard-Ausgabe": "Sortie standard",
    "Neben der Quelle": "À côté de la source",
    "Anderen Ordner wählen…": "Choisir un autre dossier…",
    "Standard-Ausgabeordner (relativ zum Medienbaum)": "Dossier de sortie standard (relatif à l'arbre média)",
    "Zielordner wählen": "Choisir le dossier cible",
    "Medien": "Médias",
    "Scan – Spuren ermitteln": "Analyser – détecter les pistes",
    "Scan – Codec/Bitrate ermitteln": "Analyser – détecter codec/débit",
    "Auto-Crop: schwarze Balken automatisch entfernen (cropdetect)": "Rognage auto : supprimer automatiquement les bandes noires (cropdetect)",
    "Auto-Crop (cropdetect)": "Rognage auto (cropdetect)",
    "Erkennt Letterbox-/Pillarbox-Ränder an mehreren Stellen und beschneidet sie vor dem Encode – spart Bitrate. VMAF-Analyse und Guardrail nutzen automatisch dieselbe beschnittene Fläche.": "Détecte les bordures letterbox/pillarbox à plusieurs endroits et les rogne avant l'encodage – économise du bitrate. L'analyse VMAF et le garde-fou utilisent automatiquement la même zone rognée.",
    "Chunked Adaptive Encoding (Segmente mit komplexitätsabhängigem CQ – nur CQ-Modus, langsamer)": "Encodage adaptatif par blocs (segments avec CQ selon la complexité – mode CQ uniquement, plus lent)",
    "Chunked Adaptive Encoding (nur CQ)": "Encodage adaptatif par blocs (CQ uniquement)",
    "CQ-Spanne (±)": "Plage de CQ (±)",
    "Aufwändige Szenen erhalten bessere Qualität (niedrigerer CQ), ruhige Szenen werden kleiner. Der eingestellte CQ ist der Mittelwert.": "Les scènes complexes obtiennent une meilleure qualité (CQ plus bas), les scènes calmes deviennent plus petites. Le CQ défini est la moyenne.",
    "Qualitäts-Guardrail: echten VMAF nach dem Encode messen": "Garde-fou de qualité : mesurer le VMAF réel après l'encodage",
    "Qualitäts-Guardrail (VMAF nach Encode)": "Garde-fou de qualité (VMAF après encodage)",
    "Ziel-VMAF (min.)": "VMAF cible (min.)",
    "Bei Unterschreiten automatisch mit höherer Qualität neu encoden": "En dessous, réencoder automatiquement avec une meilleure qualité",
    "Nach dem Encode werden Stichproben-Clips der Ausgabe gegen die Quelle gemessen. Liegt der VMAF darunter, wird (falls aktiviert) mit besserer Qualität wiederholt – sonst als Warnung markiert.": "Après l'encodage, des extraits d'échantillon de la sortie sont mesurés par rapport à la source. Si le VMAF est en dessous, l'opération est répétée avec une meilleure qualité (si activé) – sinon elle est signalée comme avertissement.",
    "Qualität": "Qualité",
    "Steuerungsmodus": "Mode de contrôle du débit",
    "CQ / QP / CRF (Qualitätszahl)": "CQ / QP / CRF (valeur de qualité)",
    "Festbitrate (CBR)": "Débit fixe (CBR)",
    "Average Bitrate (VBR-Ziel)": "Débit moyen (cible VBR)",
    "Ziel-VMAF (Test-Encodes, dann Encode)": "VMAF cible (encodages de test, puis encodage)",
    "Effizientester Testwert (kleinste Datei) mit VMAF ≥ Ziel wird automatisch encodiert.":
      "La valeur de test la plus efficace (plus petit fichier) avec VMAF ≥ cible est encodée automatiquement.",
    "Screenshots der Test-Encodes": "Captures des encodages de test",
    "Wie im VMAF-Tool, optional. Bei Ordnern nur die erste Datei (repräsentativ).":
      "Optionnel, comme dans l'outil VMAF. Pour les dossiers, uniquement le premier fichier (représentatif).",
